// app/messages/page.jsx
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import api from "@/services/api";
import Link from "next/link";

export default function MessagesPage() {
  const { user } = useAuth();
  const socket = useSocket();
  const router = useRouter();
  const [conversations, setConversations] = useState([]);

  useEffect(() => {
    if (!user) return;
    api
      .get("/api/messages/last")
      .then(({ data }) => setConversations(data))
      .catch((err) => console.error("Failed to fetch last messages:", err));
  }, [user]);

  return (
    <div className="flex h-screen">
      {/* Sidebar */}
      <div className="w-1/3 bg-white p-4 border-r overflow-y-auto">
        <h2 className="text-2xl font-bold mb-4">Messages</h2>
        {conversations.map((conv) => (
          <Link
            key={conv.user.id}
            href={`/messages/${conv.user.id}`}
            className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-100 mb-2"
          >
            <div className="flex items-center gap-3">
              <img
                src={conv.user.avatar}
                alt={conv.user.username}
                className="w-10 h-10 rounded-full"
              />
              <div>
                <p className="font-semibold">{conv.user.username}</p>
                <p className="text-sm text-gray-500 truncate w-40">
                  {conv.lastMessage.content}
                </p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-xs text-gray-400">
                {new Date(conv.lastMessage.created_at).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </p>
              {/* Remove "New" badge if already read */}
              {conv.lastMessage.sender_id === conv.user.id &&
                !conv.lastMessage.read && (
                  <span className="text-xs bg-purple-600 text-white px-2 py-0.5 rounded-full mt-1 inline-block">
                    New
                  </span>
                )}
            </div>
          </Link>
        ))}
      </div>

      {/* Right panel - shows nothing here; chat opens on /messages/[userId] */}
      <div className="w-2/3 flex items-center justify-center text-gray-500">
        <p>Select a chat to start messaging</p>
      </div>
    </div>
  );
}
